/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
Public class METPriceChangeEventProduct
{
}

Method.Source:
    /// <summary>
    /// Process the change track
    /// Kept this process light weight due to volume of records
    /// </summary>
    public static void metProcessTrackChange(InventTable _inventTable, InventDimId  _inventDimId = '', InventSiteId _inventSiteId = '')
    {
        METPriceChangeTracking  priceChangeTracking;

        try
        {
            if (_inventTable.ItemType == ItemType::Item)
            {
                ttsbegin;
                priceChangeTracking.clear();
                                
                priceChangeTracking.SourceCrud  = SysAppCRUDOperation::Create;
                priceChangeTracking.ChangeType  = METPriceChangeType::Product;
                priceChangeTracking.setCommonValues(_inventTable);
                priceChangeTracking.QuantityAmountFrom = 1;
                priceChangeTracking.ItemId      = _inventTable.ItemId;
                priceChangeTracking.FromDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
                priceChangeTracking.UnitId      = InventTableModule::find(_inventTable.ItemId, ModuleInventPurchSales::Sales).UnitId;
                priceChangeTracking.InventSiteId = _inventSiteId ? _inventSiteId : InventDim::metGetInventDimensionFromId(_inventDimId, fieldNum(InventDim, InventSiteId));

                priceChangeTracking.insert();
                ttscommit;
            }
        }
        catch
        {
            Error("@MET:PriceChangeTrackingCreationFailed");
        }
    }
